using System;using System.Linq;using System.IO;using System.Text.Json;using System.Collections.Generic;using TownOfHost;using TownOfHost.Roles.Core;using TownOfHost.Modules;
partial class Program{
static int passed;
static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Setup(){OptionItem.Reset();Options.Reset();Logger.Errors.Clear();Logger.Warnings.Clear();RPC.Sent.Clear();AmongUsClient.Instance.Packets.Clear();AmongUsClient.Instance.AmHost=true;PlayerCatch.HasMod=false;OptionSaver.SaveCalls=0;CustomRoleManager.AllRolesInfo.Clear();
AuditDefs.Destroyer.RoleInfo=new(){RoleName=CustomRoles.Destroyer,ConfigId=39991,CustomRoleType=CustomRoleTypes.Impostor,Tab=TabGroup.ImpostorRoles,OptionSort=(0,8),OptionCreator=AuditDefs.Destroyer.Initialize};AuditDefs.Lethe.RoleInfo=new(){RoleName=CustomRoles.Lethe,ConfigId=39990,CustomRoleType=CustomRoleTypes.Crewmate,Tab=TabGroup.CrewmateRoles,OptionSort=(0,7),OptionCreator=AuditDefs.Lethe.Initialize};AuditDefs.ShrineMaiden.RoleInfo=new(){RoleName=CustomRoles.ShrineMaiden,ConfigId=40000,CustomRoleType=CustomRoleTypes.Crewmate,Tab=TabGroup.CrewmateRoles,OptionSort=(3,4),OptionCreator=AuditDefs.ShrineMaiden.Initialize};
foreach(var i in new[]{AuditDefs.Lethe.RoleInfo,AuditDefs.Destroyer.RoleInfo,AuditDefs.ShrineMaiden.RoleInfo})CustomRoleManager.AllRolesInfo.Add(i.RoleName,i);
var sorted=CustomRoleManager.AllRolesInfo.Values.OrderBy(i=>i.ConfigId);Options.CreateRoleOption(sorted,CustomRoleTypes.Impostor);Options.CreateRoleOption(sorted,CustomRoleTypes.Madmate);Options.CreateRoleOption(sorted,CustomRoleTypes.Crewmate);Options.CreateRoleOption(sorted,CustomRoleTypes.Neutral);}
static void Test(string n,Action a){Setup();a();passed++;Console.WriteLine("PASS "+n);}static OptionItem[] Recovered()=>ShellOptionIds.RecoveredOptionIds.Select(id=>OptionItem.FastOptions[id]).ToArray();static OptionSaver.SerializableOptionsData Copy(OptionSaver.SerializableOptionsData d)=>JsonSerializer.Deserialize<OptionSaver.SerializableOptionsData>(JsonSerializer.Serialize(d));
static OptionSaver.SerializableOptionsData Legacy(){var d=Copy(OptionSaver.Export());foreach(var id in ShellOptionIds.RecoveredOptionIds)d.PresetOptions.Remove(id);return d;}
static void Defaults(){foreach(var o in Recovered())Check(o.AllValues.All(v=>v==o.DefaultValue),"not definition default: "+o.Id);}
static string LegacyText(params (int id,int value)[] entries){var last=0;var text="";foreach(var e in entries.OrderBy(e=>e.id)){var delta=e.id-last;text+=Base62.ToBase62(delta)+","+Base62.ToBase62(e.value)+"!";last=e.id;}return text;}
static void Main(){
Test("all seven options are registered without constructor rejection",()=>{Check(Logger.Errors.Count==0,"duplicate registration");Check(Recovered().Length==7&&OptionItem.AllOptions.Select(o=>o.Id).Distinct().Count()==OptionItem.AllOptions.Count,"duplicate registry");});
Test("all six preexisting winning identities are preserved",()=>{Check(ReferenceEquals(OptionItem.FastOptions[39991],Options.CustomRoleSpawnChances[CustomRoles.Destroyer]),"39991");Check(ReferenceEquals(OptionItem.FastOptions[40000],AuditDefs.Lethe.OptNeedTasks),"40000");Check(ReferenceEquals(OptionItem.FastOptions[40001],AuditDefs.Destroyer.OptKillCooldown),"40001");Check(ReferenceEquals(OptionItem.FastOptions[40002],AuditDefs.Destroyer.OptShowKillFlash),"40002");Check(OptionItem.FastOptions[40003].Name=="Killdistance"&&ReferenceEquals(OptionItem.FastOptions[40004],AuditDefs.Destroyer.OptCrushTime),"40003/4");});
Test("recovered IDs and actual definition defaults are correct",()=>{Check(Recovered().Select(o=>o.DefaultValue).SequenceEqual(new[]{0,0,1,1,1,0,0}),"defaults");Defaults();Check(Options.CustomRoleCounts[CustomRoles.Lethe].GetInt()==1&&Options.CustomRoleCounts[CustomRoles.ShrineMaiden].GetInt()==1,"max defaults");});
Test("Lethe task child parents and role parents are preserved",()=>{Check(AuditDefs.Lethe.OptRequiredTaskCount.Parent==AuditDefs.Lethe.OptNeedTasks&&AuditDefs.Lethe.OptHideUntilTasks.Parent==AuditDefs.Lethe.OptNeedTasks,"task parent");Check(AuditDefs.Lethe.OptGiveSealer.Parent==AuditDefs.Lethe.RoleInfo.RoleOption&&AuditDefs.Lethe.OptGiveSecurer.Parent==AuditDefs.Lethe.RoleInfo.RoleOption,"role parent");});
Test("role header references use separate IDs with stable ConfigId",()=>{Check(AuditDefs.ShrineMaiden.RoleInfo.ConfigId==40000&&AuditDefs.Lethe.RoleInfo.ConfigId==39990&&AuditDefs.Destroyer.RoleInfo.ConfigId==39991,"ConfigId changed");Check(Options.CustomRoleSpawnChances[CustomRoles.ShrineMaiden].Id==1800005&&Options.CustomRoleCounts[CustomRoles.ShrineMaiden].Id==1800006&&Options.CustomRoleCounts[CustomRoles.Lethe].Id==1800000,"header mappings");});
Test("recovered options remain discoverable in role UI enumeration",()=>{foreach(var o in Recovered())Check(OptionItem.AllOptions.Contains(o)&&(o.Id==ShellOptionIds.ShrineMaidenSpawn?o.IsHeader:o.Parent!=null&&o.Parent.Children.Contains(o)),"UI orphan");});
Test("JSON includes seven distinct entries and all supported presets",()=>{var d=OptionSaver.Export();Check(ShellOptionIds.RecoveredOptionIds.All(id=>d.PresetOptions.ContainsKey(id)&&d.PresetOptions[id].Length==OptionItem.NumPresets),"save omitted recovered field");Check(OptionItem.NumPresets==7,"unexpected preset count");});
Test("old colliding values are never copied into new settings",()=>{var d=Legacy();d.PresetOptions[39991]=Enumerable.Repeat(7,OptionItem.NumPresets).ToArray();d.PresetOptions[40000]=Enumerable.Repeat(0,OptionItem.NumPresets).ToArray();d.PresetOptions[40001]=Enumerable.Repeat(23,OptionItem.NumPresets).ToArray();OptionSaver.Import(d);Defaults();Check(Options.CustomRoleSpawnChances[CustomRoles.Destroyer].GetInt()==70&&AuditDefs.Destroyer.OptKillCooldown.GetFloat()==43,"legacy winning value lost");});
Test("loading an old file after edits resets only missing recovery entries",()=>{var d=Legacy();foreach(var o in Recovered())o.SetAllValues(Enumerable.Repeat(o.DefaultValue==0?1:0,OptionItem.NumPresets).ToArray());OptionSaver.Import(d);Defaults();});
Test("seven legacy preset arrays survive unchanged",()=>{var d=Legacy();d.PresetOptions[39991]=Enumerable.Range(0,OptionItem.NumPresets).ToArray();d.PresetOptions[40001]=Enumerable.Range(10,OptionItem.NumPresets).ToArray();OptionSaver.Import(d);var saved=OptionSaver.Export();Check(saved.PresetOptions[39991].SequenceEqual(d.PresetOptions[39991])&&saved.PresetOptions[40001].SequenceEqual(d.PresetOptions[40001]),"legacy array changed");});
Test("new JSON roundtrip preserves zero and nonzero in every preset",()=>{foreach(var o in Recovered())for(int n=0;n<OptionItem.NumPresets;n++)o.AllValues[n]=o is BooleanOptionItem?n%2:n%3;var d=Copy(OptionSaver.Export());Setup();OptionSaver.Import(d);var saved=OptionSaver.Export();foreach(var id in ShellOptionIds.RecoveredOptionIds)Check(saved.PresetOptions[id].SequenceEqual(d.PresetOptions[id]),"new array lost");});
Test("version four load does not save defaults over the file or rename presets",()=>{TownOfHost.Main.Preset1.Value="unchanged";var d=Legacy();OptionSaver.Import(d);Check(OptionSaver.Version==4&&OptionSaver.SaveCalls==0&&TownOfHost.Main.Preset1.Value=="unchanged","destructive version reset");});
Test("synthetic numeric settings roundtrip without reading personal settings",()=>{var fixture=Copy(OptionSaver.Export());fixture.SingleOptions[1900000]=42;fixture.PresetOptions[1900001]=Enumerable.Range(0,OptionItem.NumPresets).ToArray();var raw=JsonSerializer.Serialize(fixture);var d=JsonSerializer.Deserialize<OptionSaver.SerializableOptionsData>(raw);d.AssignOptions.Clear();foreach(var key in d.SingleOptions.Keys)if(!OptionItem.FastOptions.ContainsKey(key))new OptionItem(key,"preserved",0,TabGroup.MainSettings,true);foreach(var key in d.PresetOptions.Keys)if(!OptionItem.FastOptions.ContainsKey(key))new OptionItem(key,"preserved",0,TabGroup.MainSettings,false);OptionSaver.Import(d);var saved=OptionSaver.Export();foreach(var e in d.SingleOptions)Check(saved.SingleOptions[e.Key]==e.Value,"single changed");foreach(var e in d.PresetOptions)Check(saved.PresetOptions[e.Key].SequenceEqual(e.Value.Take(OptionItem.NumPresets)),"preset changed: "+e.Key);Defaults();});
Test("ShrineMaiden assignment ConfigId cannot become a Lethe detail",()=>{var assign=new AssignOptionItem(1900000);var d=Legacy();d.AssignOptions[assign.Id]=new(){{0,new[]{40000}}};OptionSaver.Import(d);Check(assign.RoleValues[0].SequenceEqual(new[]{CustomRoles.ShrineMaiden}),"assignment identity confused");});
Test("existing Lethe and Destroyer assignment identities survive",()=>{var assign=new AssignOptionItem(1900000);var d=Legacy();d.AssignOptions[assign.Id]=new(){{0,new[]{39990,39991}}};OptionSaver.Import(d);Check(assign.RoleValues[0].SequenceEqual(new[]{CustomRoles.Lethe,CustomRoles.Destroyer}),"assignment changed");});
Test("new assignment saves stable ConfigId rather than remapped option ID",()=>{var assign=new AssignOptionItem(1900000);assign.RoleValues[0]=new(){CustomRoles.ShrineMaiden};var d=OptionSaver.Export();Check(d.AssignOptions[assign.Id][0].SequenceEqual(new[]{40000}),"ConfigId format changed");});
Test("old clipboard defaults recovered fields without interpreting old IDs",()=>{OptionSerializer.LoadModOptionsString(LegacyText((39991,7),(40001,23)));Defaults();Check(Options.CustomRoleSpawnChances[CustomRoles.Destroyer].GetInt()==70&&AuditDefs.Destroyer.OptKillCooldown.GetFloat()==43,"legacy clipboard");});
Test("old clipboard still uses zero omission for legacy settings",()=>{OptionSerializer.LoadModOptionsString("");Check(Options.CustomRoleSpawnChances[CustomRoles.Destroyer].GetValue()==0&&AuditDefs.Lethe.OptNeedTasks.GetValue()==0,"legacy zero behavior changed");Defaults();});
Test("new clipboard explicitly stores zero-valued recovered settings",()=>{foreach(var o in Recovered())o.SetValue(0,false,false);var encoded=OptionSerializer.GenerateModOptionsString();foreach(var o in Recovered())o.SetValue(o.DefaultValue==0?1:0,false,false);OptionSerializer.LoadModOptionsString(encoded);Check(Recovered().All(o=>o.GetValue()==0),"zero became default");});
Test("new clipboard roundtrip preserves nonzero recovered settings",()=>{foreach(var o in Recovered())o.SetValue(1,false,false);var encoded=OptionSerializer.GenerateModOptionsString();Setup();OptionSerializer.LoadModOptionsString(encoded);Check(Recovered().All(o=>o.GetValue()==1),"clipboard roundtrip");});
Test("single-item RPC for Lethe maximum cannot alter Destroyer rate",()=>{PlayerCatch.HasMod=true;Options.CustomRoleCounts[CustomRoles.Lethe].SetValue(6);var packets=AmongUsClient.Instance.Packets.Select(p=>p.ToArray()).ToArray();Check(packets.Length==1&&packets[0][0]==1800000,"wrong wire ID");Setup();AmongUsClient.Instance.AmHost=false;RPC.Receive(new(packets[0]));Check(Options.CustomRoleCounts[CustomRoles.Lethe].GetInt()==7&&Options.CustomRoleSpawnChances[CustomRoles.Destroyer].GetInt()==0,"cross-option sync");});
Test("single-item RPC keeps original Destroyer rate ID",()=>{PlayerCatch.HasMod=true;Options.CustomRoleSpawnChances[CustomRoles.Destroyer].SetValue(6);var data=AmongUsClient.Instance.Packets.Single();Setup();AmongUsClient.Instance.AmHost=false;RPC.Receive(new(data));Check(data[0]==39991&&Options.CustomRoleSpawnChances[CustomRoles.Destroyer].GetInt()==60&&Options.CustomRoleCounts[CustomRoles.Lethe].GetInt()==1,"legacy wire identity");});
Test("single-item RPC for Shrine chance cannot alter Lethe task awakening",()=>{PlayerCatch.HasMod=true;Options.CustomRoleSpawnChances[CustomRoles.ShrineMaiden].SetValue(4);var data=AmongUsClient.Instance.Packets.Single();Setup();AmongUsClient.Instance.AmHost=false;RPC.Receive(new(data));Check(data[0]==1800005&&Options.CustomRoleSpawnChances[CustomRoles.ShrineMaiden].GetInt()==40&&AuditDefs.Lethe.OptNeedTasks.GetValue()==1,"Shrine cross sync");});
Test("actual full-sync sender and receiver preserve every option",()=>{foreach(var o in Recovered())o.SetValue(1,false,false);var expected=OptionItem.AllOptions.ToDictionary(o=>o.Id,o=>o.GetValue());PlayerCatch.HasMod=true;RPC.SyncCustomSettingsRPC();var data=AmongUsClient.Instance.Packets.Select(p=>p.ToArray()).ToArray();Setup();AmongUsClient.Instance.AmHost=false;foreach(var packet in data)RPC.Receive(new(packet));Check(OptionItem.AllOptions.All(o=>expected[o.Id]==o.GetValue()),"full sync mismatch");});
Test("full-sync chunk boundary remains correct beyond 500 settings",()=>{for(int n=0;n<510;n++)new OptionItem(2000000+n,"chunk",n,TabGroup.MainSettings,false);var expected=OptionItem.AllOptions.Select(o=>o.GetValue()).ToArray();PlayerCatch.HasMod=true;RPC.SyncCustomSettingsRPC();var packets=AmongUsClient.Instance.Packets.Select(p=>p.ToArray()).ToArray();Check(packets.Length==2&&packets[1][1]==500,"chunk header");foreach(var o in OptionItem.AllOptions)o.SetValue(0,false,false);AmongUsClient.Instance.AmHost=false;foreach(var packet in packets)RPC.Receive(new(packet));Check(OptionItem.AllOptions.Select(o=>o.GetValue()).SequenceEqual(expected),"chunk restore");});
Test("nonhost cannot emit custom-setting sync",()=>{PlayerCatch.HasMod=true;AmongUsClient.Instance.AmHost=false;RPC.SyncCustomSettingsRPC();RPC.SyncCustomSettingsRPC(Recovered()[0]);Check(AmongUsClient.Instance.Packets.Count==0,"nonhost transmission");});
Test("new ID range does not include neighboring IDs",()=>{Check(!ShellOptionIds.IsRecoveredOption(1799999)&&!ShellOptionIds.IsRecoveredOption(1800007)&&ShellOptionIds.RecoveredOptionIds.All(ShellOptionIds.IsRecoveredOption),"range");});
Test("unrelated role header IDs are not remapped",()=>{Check(ShellOptionIds.SpawnChanceId(CustomRoles.Destroyer,39991)==39991&&ShellOptionIds.MaximumId(CustomRoles.Destroyer,39992)==39992&&ShellOptionIds.SpawnChanceId(CustomRoles.Lethe,39990)==39990,"unrelated mapping");});
EliminatorRenameTests();
Console.WriteLine($"RESULT {passed} passed, 0 failed; NumPresets={OptionItem.NumPresets}");}}
